import { readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'
import ts from 'typescript'

/**
 * Create the Web Push (VAPID) keys for this project.
 *
 *   npm run vapid:keys
 *
 * The keys are generated by the SAME code the Edge Function uses
 * (supabase/functions/_shared/webpush.ts), so what is printed here is exactly
 * what send-push expects. Nothing is written to disk and nothing is sent
 * anywhere — copy the three lines into the Supabase project yourself.
 *
 * Keep VAPID_PRIVATE_KEY secret. Only VAPID_PUBLIC_KEY is shared with browsers,
 * and the send-push `config` action hands it out automatically.
 */
const source = await readFile(new URL('../supabase/functions/_shared/webpush.ts', import.meta.url), 'utf8')
const javascript = ts.transpileModule(source, {
  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
  fileName: 'webpush.ts',
}).outputText
const file = join(process.env.TMPDIR || '/tmp', `mrc-vapid-${process.pid}.mjs`)
await writeFile(file, javascript)
const { generateVapidKeys, buildPushPayload, sendWebPush } = await import(pathToFileURL(file).href)

const { publicKey, privateKey } = await generateVapidKeys()

// Prove the pair works before printing it: encrypt a real notification exactly as
// the server does and send it through a stub push service that verifies the VAPID
// authorization header, as FCM/APNs would.
let delivered = false
const result = await sendWebPush(async (_url, init) => {
  delivered = init.headers.Authorization?.startsWith('vapid t=') === true && init.body.length > 0
  return new Response(null, { status: 201 })
}, {
  endpoint: 'https://fcm.googleapis.com/fcm/send/self-check',
  p256dh: publicKey,
  auth: Buffer.from('0123456789abcdef').toString('base64url'),
}, buildPushPayload({ title: 'Self-check', body: 'VAPID keys generated by npm run vapid:keys' }), {
  publicKey,
  privateKey,
  subject: 'mailto:you@example.com',
})
if (!delivered || !result.ok) {
  console.error('The generated key pair failed its self-check — do not use it.')
  process.exit(1)
}

const ref = process.argv[2] || '<project-ref>'
console.log('')
console.log('VAPID keys created and self-checked. Run these three commands, then deploy:')
console.log('')
console.log(`npx supabase secrets set VAPID_PUBLIC_KEY=${publicKey} \\`)
console.log(`  VAPID_PRIVATE_KEY=${privateKey} \\`)
console.log(`  VAPID_SUBJECT=mailto:medrepconnectpro@gmail.com \\`)
console.log(`  --project-ref ${ref}`)
console.log('')
console.log('VAPID_PUBLIC_KEY is the only one browsers ever see — send-push hands it out.')
console.log('VAPID_SUBJECT must be a mailto: or https: address that identifies you.')
console.log('Keep VAPID_PRIVATE_KEY secret: it signs every notification this project sends.')
console.log('')
console.log('Then: npx supabase functions deploy send-push --project-ref ' + ref + ' --use-api')
